// tcgen05.mma reads A/B from SMEM, accumulates into TMEM
// Block scale applied natively during MMA
asm volatile(
    "tcgen05.mma.cta_group::1.kind::f8f6f4"
    " [%0], %1, %2, %3, %4;"
    :
    : "l"(tmem_addr), "l"(a_smem_addr), "l"(b_smem_addr),
      "r"(packed_scales), "n"(SCALE_D_ENABLED)
